"""Normalize release records at the input boundary.

Everything here happens *before* accounting and graph construction: the
planner only ever sees one canonical record per change ID, so "collapse
duplicates first, then count units / build the graph" cannot be bypassed.
"""


class JournalError(ValueError):
    pass


def _is_int(value):
    # bool is a subclass of int but is not a count; SPEC excludes booleans.
    return type(value) is int


def _read_dependencies(row, change_id):
    raw = row.get("depends_on")
    if raw is None:
        return frozenset()
    if not isinstance(raw, list):
        raise JournalError("invalid-change")
    for dep in raw:
        if not isinstance(dep, str) or not dep:
            raise JournalError("invalid-change")
        if dep == change_id:
            # A record depending on itself is a cycle, and relying on the
            # graph pass to notice it would report a different error code.
            raise JournalError("dependency-cycle")
    # Order inside depends_on is not identity: compare as a set.
    return frozenset(raw)


def read_changes(records):
    """Return canonical change records, deduplicated by ID.

    Equality covers id, component, units and the set of dependencies.
    Identical duplicates collapse to one; any difference is a conflict so
    the caller never has to guess which copy was "the real" release.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or not _is_int(row.get("units")) or row["units"] < 1):
            raise JournalError("invalid-change")
        change_id = row["id"]
        record = {
            "id": change_id,
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row, change_id),
        }
        seen = changes.get(change_id)
        if seen is None:
            changes[change_id] = record
        elif seen != record:
            raise JournalError("conflicting-change")
    return list(changes.values())


def read_applied(applied):
    """Read the caller's persisted release journal.

    This is a *record of what already happened*, so it is not deduplicated or
    checked against `changes` here; unknown IDs are a graph concern and are
    reported by the planner as `unknown-dependency`.
    """
    if applied is None:
        return frozenset()
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    for applied_id in applied:
        if not isinstance(applied_id, str) or not applied_id:
            raise JournalError("invalid-change")
    return frozenset(applied)

