"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _graph(changes, applied):
    """Build the dependency graph, failing closed on anything incomplete.

    Edge direction is `dependency -> dependent`: `successors[d]` lists the
    changes that must wait for d, and `indegree[c]` counts c's dependencies.
    A topological order of this graph therefore emits dependencies first.
    """
    ids = {row["id"] for row in changes}
    # `applied` is a record of the caller's own history. An ID we have never
    # heard of means the input and the journal disagree, so we refuse to plan
    # rather than silently treat the graph as complete.
    for applied_id in applied:
        if applied_id not in ids:
            raise JournalError("unknown-dependency")
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in ids:
                raise JournalError("unknown-dependency")
    successors = {change_id: [] for change_id in ids}
    indegree = {change_id: 0 for change_id in ids}
    for row in changes:
        for dep in row["depends_on"]:
            successors[dep].append(row["id"])
            indegree[row["id"]] += 1
    return successors, indegree


def execution_order(changes, applied):
    """Full deterministic topological order, independent of `applied`.

    Kubernetes-style tie-breaking: among changes whose dependencies are all
    already emitted, always take the lexicographically smallest ID. The order
    is computed over *all* changes even for `plan`, so budget and rollback see
    the same sequence a full deployment would follow.
    """
    successors, indegree = _graph(changes, applied)
    ready = [change_id for change_id, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in successors[change_id]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(indegree):
        # Some node still waits on a dependency. Nothing has been emitted, so
        # the caller gets no partial actions.
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        order = execution_order(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
    if request["action"] == "plan":
        # Replay: applied changes already exist, so they are skipped and do not
        # consume new budget. The budget check runs on the replayed set only,
        # never on the raw request.
        emitted = [change_id for change_id in order if change_id not in applied]
        units = sum(units_by_id[change_id] for change_id in emitted)
        if units > budget:
            return failure("budget-exceeded")
    else:
        # Rollback is the mirror of rollout: reverse of the full order, limited
        # to what was actually applied. The budget field is validated but does
        # not cap a rollback.
        emitted = [change_id for change_id in reversed(order) if change_id in applied]
        units = sum(units_by_id[change_id] for change_id in emitted)
    return {"status": "ok", "actions": emitted, "units": units}

