"""Validate release policy before computing actions."""


class PlanError(ValueError):
    """Base failure type so the planner can catch every layer's rejection uniformly.

    Lives in this leaf module (policy imports nothing else) because both journal and
    planner need it, and the import direction release -> planner -> {policy, journal}
    forbids journal or policy from importing the planner.
    """


class PolicyError(PlanError):
    pass


# G1 enables both directions in both environments. Anything else stays
# `unsupported-action` so unknown verbs are rejected rather than guessed.
ACTIONS = {"plan", "rollback"}


def limit_for(request):
    if request.get("environment") not in {"staging", "production"}:
        raise PolicyError("invalid-environment")
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    # `type(...) is int` deliberately rejects bool (a subclass of int) and floats.
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    # Rollback is a safety operation: the budget is still validated here, but the
    # planner must not use this limit to cap a rollback.
    return budget

