"""Normalize release records at the input boundary."""
from policy import PlanError


class JournalError(PlanError):
    pass


def read_changes(records):
    """Validate change records and normalize `depends_on` to a list of IDs.

    Order of `depends_on` is preserved here; replay identity below compares it as a
    set, because the graph only cares about which edges exist, not their input order.
    """
