    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = row.get("depends_on", [])
        if not isinstance(depends_on, list):
            raise JournalError("invalid-change")
        for dependency in depends_on:
            if not isinstance(dependency, str) or not dependency:
                raise JournalError("invalid-change")
        changes.append({
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": list(depends_on),
        })
    return changes


def replay_changes(changes):
    """Collapse identical duplicate records; reject conflicting duplicates.

    Replay identity per SPEC: (id, component, units, set(depends_on)). Records that
    describe the same change may legitimately differ in *order* of dependencies, so
    the dependency list is compared as a frozenset -- two records with the same set
    are one change and are accounted once. A duplicate ID whose identity differs is a
    conflicting replay and fails closed.
    """
    collapsed = {}
    for change in changes:
        identity = (change["component"], change["units"], frozenset(change["depends_on"]))
        existing = collapsed.get(change["id"])
        if existing is None:
            collapsed[change["id"]] = change
        elif (existing["component"], existing["units"],
              frozenset(existing["depends_on"])) != identity:
            raise JournalError("conflicting-change")
    return list(collapsed.values())


def read_retain(records):
    """Validate the G2 rollback `retain` list (IDs that must stay applied).

    The default is the empty list, so omitting `retain` keeps the G1 rollback
    behavior. Whether a retained ID is actually applied is a planner decision: the
    journal layer only validates shape, and reports malformed shape as
    `invalid-retain` rather than the generic `invalid-change`.
    """
    if records is None or not isinstance(records, list):
        raise JournalError("invalid-retain")
    retain = []
    seen = set()
    for entry in records:
        if not isinstance(entry, str) or not entry:
            raise JournalError("invalid-retain")
        # Membership only matters for retention, so repeats collapse like the journal.
        if entry not in seen:
            seen.add(entry)
            retain.append(entry)
    return retain


def read_applied(records):
    """Validate the caller-supplied persisted journal of already applied IDs."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    applied = []
    seen = set()
    for entry in records:
        if not isinstance(entry, str) or not entry:
            raise JournalError("invalid-change")
        # The journal is a set of IDs; repeating one adds nothing, and collapsing it
        # here means downstream checks cannot double-count or double-emit an entry.
        if entry not in seen:
            seen.add(entry)
            applied.append(entry)
    return applied

