"""Compose policy and journal data into a plan, including graph order."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain, replay_changes
from policy import PlanError, limit_for


class GraphError(PlanError):
    pass


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes):
    """Return {id: set(dependency ids)} after checking every edge has a target.

    Graph direction is dependency -> dependent: an entry becomes eligible once every
    change it depends on has been emitted. Keeping that direction explicit is what
    lets `plan` (forward order) and `rollback` (reverse of the same order) share one
    deterministic sequence.
    """
    ids = {change["id"] for change in changes}
    graph = {}
    for change in changes:
        for dependency in change["depends_on"]:
            # Fail closed: a dangling edge would silently drop a prerequisite from the
            # ordering, so an unknown target is an error rather than a skipped edge.
            if dependency not in ids:
                raise GraphError("unknown-dependency")
        graph[change["id"]] = set(change["depends_on"])
    return graph


def topological_order(graph):
    """Depth-first (dependencies first) order with lexicographic tie-breaking.

    Among changes whose dependencies are all satisfied, the smallest ID is emitted
    next. That makes the order depend only on the graph, not on input array order, so
    replaying the same request always yields the same sequence -- and its reverse is a
    safe rollback order.
    """
    indegree = {}
    dependents = {node: [] for node in graph}
    for node, dependencies in graph.items():
        indegree[node] = len(dependencies)
        for dependency in dependencies:
            dependents[dependency].append(node)
    # heapq over IDs: ties are broken lexicographically among currently eligible nodes.
    eligible = [node for node, degree in indegree.items() if degree == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        node = heapq.heappop(eligible)
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(eligible, dependent)
    if len(order) != len(graph):
        # Leftover nodes can only mean a cycle, including a self-dependency.
        raise GraphError("dependency-cycle")
    return order


def assemble(request):
    """Validate, replay, order and select the changes this request may emit.

    Stages run in a fixed order so an error is reported before any action is chosen:
    policy (environment/action/budget, plus the G2 production freeze) -> journal shape
    -> replay identity -> graph shape -> order -> applied-journal identity -> G2
    retain identity. No stage returns partial actions.
    """
    budget = limit_for(request)
    # Replay must happen before the graph is built: deduplicated IDs are the only ones
    # that exist for ordering/accounting, and conflicting replays fail here.
    changes = replay_changes(read_changes(request.get("changes")))
    graph = build_graph(changes)
    order = topological_order(graph)
    known = {change["id"] for change in changes}
    applied = read_applied(request.get("applied", []))
    # Unknown IDs in the persisted journal are checked against the replayed IDs: the
    # journal must name changes this request actually knows about.
    for entry in applied:
        if entry not in known:
            raise JournalError("unknown-dependency")
    # G2 retention only exists for rollback, and `retain` must name IDs that are
    # already applied -- retaining an unapplied change is meaningless, so it is
    # rejected (`invalid-retain`) instead of being silently ignored.
    retain = read_retain(request.get("retain", [])) if request["action"] == "rollback" else []
    applied_ids = set(applied)
    for entry in retain:
        if entry not in applied_ids:
            raise JournalError("invalid-retain")
    return budget, changes, order, graph, applied_ids, retain


def _retained(graph, applied, retain):
    """Applied IDs kept installed: each retained change plus its applied dependencies.

    Dependencies are followed transitively so a retained change never survives on top
    of a rollback that removed a prerequisite. Only applied nodes are collected: an
    unapplied dependency is not part of the rollback output anyway.
    """
    kept = set()
    pending = [entry for entry in retain if entry in applied]
    while pending:
        node = pending.pop()
        if node in kept:
            continue
        kept.add(node)
        for dependency in graph[node]:
            if dependency in applied and dependency not in kept:
                pending.append(dependency)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget, changes, order, graph, applied, retain = assemble(request)
    except PlanError as exc:
        return failure(str(exc))
    units_by_id = {change["id"]: change["units"] for change in changes}
    if request["action"] == "rollback":
        # Reverse of the full deterministic order, restricted to applied changes and
        # minus the G2 retained closure. Filtering after reversing keeps the emitted
        # order identical to G1 up to the removed IDs.
        # The budget was validated but must not cap a rollback, so `budget` is unused here.
        kept = _retained(graph, applied, retain)
        actions = [node for node in reversed(order) if node in applied and node not in kept]
    else:
        # Forward order, restricted to changes not yet in the persisted journal.
        # Already applied entries satisfy dependencies but emit nothing and cost nothing.
        actions = [node for node in order if node not in applied]
        # Budget is compared only against what this request actually emits, i.e. after
        # replay/dedup and after dropping already applied entries.
        if sum(units_by_id[node] for node in actions) > budget:
            return failure("budget-exceeded")
    # `units` always counts exactly the emitted actions, so callers can trust
    # units == sum(units of actions emitted) in both directions.
    return {
        "status": "ok",
        "actions": actions,
        "units": sum(units_by_id[node] for node in actions),
    }

