"""Validate release policy before computing actions."""


class PlanError(ValueError):
    """Base failure type so the planner can catch every layer's rejection uniformly.

    Lives in this leaf module (policy imports nothing else) because both journal and
    planner need it, and the import direction release -> planner -> {policy, journal}
    forbids journal or policy from importing the planner.
    """


class PolicyError(PlanError):
    pass


# G2 is staging-only: both verbs stay in the grammar (so an unknown verb is still
# `unsupported-action`, not frozen) but production is refused by `limit_for` below.
ACTIONS = {"plan", "rollback"}

# G2 budget ceiling for staging. The effective limit is always the smaller of the
# request budget and this cap, so a generous request cannot widen the release window.
STAGING_LIMIT = 3


def limit_for(request):
    if request.get("environment") not in {"staging", "production"}:
        raise PolicyError("invalid-environment")
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    # `type(...) is int` deliberately rejects bool (a subclass of int) and floats.
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    # G2 freezes production for BOTH verbs, and this check runs before the journal,
    # graph and change stages: a frozen request must fail closed as
    # `production-frozen` even when its graph is malformed, never as a graph error.
    if request["environment"] == "production":
        raise PolicyError("production-frozen")
    # Rollback is a safety operation: the budget is still validated here, but the
    # planner must not use the returned limit to cap a rollback. A staging plan gets
    # min(request, cap) so the cap also wins when the request itself would allow more.
    return min(budget, STAGING_LIMIT)

release.py.text:
"""JSON transport for the release planner."""
import json
import sys

from planner import plan


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        try:
            result = plan(request)
        except Exception:
            # Transport stays fail-closed: the contract says every request exits normally
            # with a JSON result, so an unexpected planner fault must not leak a traceback.
            result = {"status": "error", "error": "invalid-request", "actions": [], "units": 0}
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

