"""Compose policy and journal data into a plan.

Import direction is one-way: planner may import policy and journal, never the
reverse. That keeps transport (release.py) at the top, orchestration here in
the middle, and the leaf-level validators below -- so the graph code can be
reasoned about without dragging in the entrypoint.
"""
import heapq

from journal import JournalError, read_changes, read_applied
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes, applied):
    """Deterministic rollout order over *all* changes, applied or not.

    Graph direction: an edge `c -> d` (c depends on d) is stored as an incoming
    edge on `c` and an outgoing edge on `d`, so a change only becomes eligible
    once every prerequisite has been emitted. Missing targets are rejected
    before any ordering happens.

    Tie-break: among currently eligible changes the lexicographically smallest
    ID goes first. Eligibility is not re-sorted globally, so a small ID that
    only becomes reachable late waits its turn -- this matches "eligible", not
    "sorted overall".

    `applied` deliberately does not affect this order. Rollback must replay the
    *full* order (then reverse it); filtering applied entries during planning
    would let a partially applied release roll back in a different relative
    order than it was rolled out.
    """
    ids = {row["id"] for row in changes}
    waiting = {}
    dependents = {change_id: [] for change_id in ids}
    for row in changes:
        for target in row["depends_on"]:
            # A dangling edge means the submitted record is unbuildable; refuse
            # rather than dropping it, since that would silently release a
            # component whose prerequisite never lands.
            if target not in ids:
                raise JournalError("unknown-dependency")
            dependents[target].append(row["id"])
        waiting[row["id"]] = len(row["depends_on"])

    ready = [change_id for change_id, count in waiting.items() if count == 0]
    heapq.heapify(ready)  # heap == lexicographic min of currently eligible IDs
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for follower in dependents[current]:
            waiting[follower] -= 1
            if waiting[follower] == 0:
                heapq.heappush(ready, follower)
    # Fewer emitted than known means a cycle swallowed the rest. Deferring this
    # check until after ordering keeps it a pure post-condition on the graph.
    if len(order) != len(ids):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy first: an operation we are not allowed to perform must not be
        # able to leak information about the change set through a later error.
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"), {row["id"] for row in changes})
        order = _topological_order(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
    if request["action"] == "rollback":
        # Rollback only touches what the persisted journal says is live, and in
        # reverse rollout order so dependents go down before prerequisites.
        # Budget was validated by policy but intentionally does not cap it:
        # refusing a rollback for cost would leave a release half-torn-down,
        # which is worse than exceeding the planning budget.
        actions = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # Budget is charged against only the newly emitted units, computed after
        # replay/deduplication. Already-applied entries satisfy their
        # dependencies for free and must not consume new budget.
        actions = [change_id for change_id in order if change_id not in applied]
        units = sum(units_by_id[change_id] for change_id in actions)
        if units > budget:
            return failure("budget-exceeded")

    units = sum(units_by_id[change_id] for change_id in actions)
    return {"status": "ok", "actions": actions, "units": units}

